  /* ======================= نشاط (2) ص 116–118: محاكاة توسع الكون بالبالون ======================= */
  const CIRC = [2, 5, 8]; // بعد الدوائر عن عنق البالون (سم) قبل النفخ: 2 ثم كل دائرة تبعد 3 سم عن الأخرى
  K.reg({
    id: 'universe-expansion', unit: 10, order: 3, lesson: '3-2', lessonTitle: 'توسع الكون', page: 116,
    titleAr: 'محاكاة توسع الكون بالبالون', titleEn: 'Balloon Model of the Expanding Universe',
    tags: 'توسع الكون تمدد بالون دوائر اشكال مسافه عنق البالون هابل 1929 تباعد المجرات دوبلر نشاط 2',
    formula: '\\text{المسافة بعد النفخ} = \\text{المسافة الأولى} \\times \\text{معامل التمدد}',
    book: 'نشاط (2) ص 116–118: تُرسم على بالون منفوخ قليلاً ثلاث دوائر، أقربها على بعد 2 سم من العنق وبين كل دائرتين 3 سم، وعلى كل دائرة ثلاثة أشكال متساوية التباعد، ثم يُنفخ البالون ويضاعف حجمه وتسجل المسافات. ص 118: لاحظ هابل عام 1929 أن المجرات في تباعد مستمر بسرعات هائلة.',
    summary: 'عند نفخ البالون تتباعد كل الأشكال عن بعضها، والأبعد يبتعد أكثر. سطح البالون يمثل الكون، والنفخ تمدده، والأشكال المجرات: لا مركز للتمدد، وكل مجرة ترى غيرها تبتعد عنها.',
    vars: [['\\text{معامل التمدد}', 'كم مرة تضاعفت أبعاد البالون (1 قبل النفخ)', '—', '1 – 4'], ['\\text{المسافة}', 'بعد كل دائرة عن العنق', '\\mathrm{cm}', '—']],
    assumptions: ['البالون يتمدد بانتظام، فتتضاعف المسافات جميعها بالمعامل نفسه (نموذج مبسّط لأغراض التعليم).'],
    params: [{ key: 'k', label: '\\text{معامل التمدد}', min: 1, max: 4, step: 0.5, value: 1 }],
    play: { key: 'k', speed: 0.6, bounce: true },
    compute(p) { return { dist: CIRC.map((x) => x * p.k), gap: 3 * p.k, shapes: 2 * p.k }; },
    drawCustom(ctx, W, H, p, d, c) {
      const nar = K.narrow(W); const cx = W / 2, cy = H * 0.46; const R = Math.min(W, H) * 0.1 * (1 + (p.k - 1) * 0.45);
      ctx.fillStyle = 'rgba(244,63,94,.35)'; ctx.strokeStyle = '#be123c'; ctx.lineWidth = 2; ctx.beginPath(); ctx.ellipse(cx, cy, R, R * 1.15, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#be123c'; ctx.beginPath(); ctx.moveTo(cx - 6, cy + R * 1.15); ctx.lineTo(cx + 6, cy + R * 1.15); ctx.lineTo(cx, cy + R * 1.15 + 12); ctx.fill();
      const neck = cy + R * 1.15;
      CIRC.forEach((x0, i) => { const yy = neck - (x0 / 10) * R * 2.3 * 0.92; const half = Math.sqrt(Math.max(0, 1 - Math.pow((yy - cy) / (R * 1.15), 2))) * R; ctx.strokeStyle = 'rgba(255,255,255,.8)'; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.ellipse(cx, yy, half, half * 0.18, 0, 0, Math.PI * 2); ctx.stroke(); [-0.6, 0, 0.6].forEach((f) => { ctx.fillStyle = ['#fde047', '#22d3ee', '#a3e635'][i]; ctx.beginPath(); ctx.arc(cx + f * half, yy + Math.abs(f) * 2, 4, 0, Math.PI * 2); ctx.fill(); }); if (!nar) K.lbl(ctx, 'الدائرة ' + (i + 1) + ': ' + n(d.dist[i], 2) + ' سم', cx + R + 70, yy, c.text, c, 12); });
      if (nar) K.lbl(ctx, d.dist.map((v, i) => 'د' + (i + 1) + ' = ' + n(v, 2)).join(' ، ') + ' سم', W / 2, H * 0.9, c.text, c, 11);
      K.lbl(ctx, 'معامل التمدد ' + p.k + ' — المسافة بين الأشكال على الدائرة ≈ ' + n(d.shapes, 2) + ' سم (نموذج)', W / 2, 18, c.c5, c, nar ? 11 : 14, '800');
    },
    live(p, d) { return '2 \\times ' + p.k + ' = ' + n(d.dist[0], 3) + ' ,\\ 5 \\times ' + p.k + ' = ' + n(d.dist[1], 3) + ' ,\\ 8 \\times ' + p.k + ' = ' + n(d.dist[2], 3) + '\\ \\mathrm{cm}'; },
    results(p, d) { return d.dist.map((v, i) => ['بعد الدائرة ' + (i + 1) + ' عن العنق', n(v, 3) + '\\ \\mathrm{cm}', true]).concat([['ما ابتعدته الدائرة 3 منذ البداية', n(d.dist[2] - 8, 3) + '\\ \\mathrm{cm}', true, 'pos'], ['ما ابتعدته الدائرة 1', n(d.dist[0] - 2, 3) + '\\ \\mathrm{cm}', true]]); },
    steps(p, d) { return ['قبل النفخ: الدوائر على 2 و5 و8 سم من العنق.', 'بعد التمدد بمعامل ' + p.k + ': ' + d.dist.map((v) => n(v, 2)).join(' و') + ' سم.', 'الدائرة الأبعد تبتعد مسافة أكبر في الزمن نفسه، أي بسرعة أكبر — كما لاحظ هابل في المجرات.']; },
    graph(p, d) { return { view: { xmin: 1, xmax: 4, ymin: 0, ymax: 34 }, xLabel: 'معامل التمدد', yLabel: 'المسافة عن العنق (سم)', caption: 'كل المسافات تتضاعف بالمعامل نفسه، والأبعد يزداد بعده أسرع (ميل أكبر).', draw(G) { const c = G.colors(); const cl = [c.c4, c.c1, c.c3]; CIRC.forEach((x0, i) => { G.fn((k) => x0 * k, { color: cl[i], width: 3, domain: [1, 4] }); G.point(p.k, x0 * p.k, { color: cl[i] }); }); } }; },
    explain(a, b) { if (b.k > a.k) return ['نفخت البالون: تباعدت جميع الأشكال عن بعضها كما تتباعد المجرات.']; return []; },
    learn: ['**التحليل (ص 118):** سطح البالون يمثل الكون، والنفخ يمثل تمدده، والأشكال تمثل المجرات.', '**مهمة ص 118:** ظاهرة دوبلر (انحراف التردد) دليل قوي على صحة نظرية الانفجار العظيم.'],
    challenges: [{ q: 'ضاعف أبعاد البالون (معامل التمدد = 2): كم أصبح بعد الدائرة الثالثة؟', hint: 'معامل التمدد = 2.', init: { k: 1 }, check: (p) => p.k === 2, why: () => '16 سم: ابتعدت 8 سم، بينما ابتعدت الأولى 2 سم فقط.' }],
    tutor: [{ q: 'هل المجرات تتقارب أم تتباعد؟', k: ['تتقارب', 'تتباعد'], a: () => K.tutor('ماذا حدث للأشكال عند نفخ البالون؟', 'تتباعد، والكون في تمدد مستمر.') }]
  });
